use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(ip) = input {
        let parts: Vec<&str> = ip.split('.').collect();
        if parts.len() != 4 {
            return Value::Bool(false);
        }
        for part in parts {
            if part.len() > 3 || (part.len() > 1 && part.starts_with('0')) {
                return Value::Bool(false);
            }
            if let Ok(num) = part.parse::<i64>() {
                if num < 0 || num > 255 {
                    return Value::Bool(false);
                }
            } else {
                return Value::Bool(false);
            }
        }
        return Value::Bool(true);
    }
    Value::Bool(false)
}
